<script setup lang="ts">
import { computed, ref } from 'vue'
import { BookOpen, FileText, GitBranch, Pencil, Plus, Search, Sparkles } from 'lucide-vue-next'
import { useResource } from '../api'
import type { Detail, Employee, Knowledge } from '../types'
import { json, label } from '../format'
import PageTitle from '../components/PageTitle.vue'
import ResourceState from '../components/ResourceState.vue'
import StatusTag from '../components/StatusTag.vue'
import EntityForm from '../components/EntityForm.vue'
const knowledge = useResource<Knowledge[]>('/knowledge', []), employees = useResource<Employee[]>('/employees', []), proposals = useResource<Detail[]>('/skill-proposals', [])
const history = useResource<Detail[]>('/historical-artifacts', [])
const historyId = ref('')
const historyContent = useResource<Detail | null>(() => historyId.value ? `/historical-artifacts/${historyId.value}/content` : '', null)
const tab = ref('all'), query = ref(''), formOpen = ref(false), selected = ref(''), editRecord = ref<Record<string, unknown>>()
const detail = useResource<Knowledge | null>(() => selected.value ? `/knowledge/${selected.value}` : '', null)
const versions = useResource<Detail[]>(() => selected.value ? `/knowledge/${selected.value}/versions` : '', [])
const item = computed(() => detail.data.value || knowledge.data.value.find(entry => entry.id === selected.value))
const items = computed(() => knowledge.data.value.filter(entry => (tab.value === 'all' || entry.kind === tab.value) && (!query.value || `${entry.title} ${entry.content}`.toLowerCase().includes(query.value.toLowerCase()))))
const versionIndex = ref(-1)
const versionContent = computed(() => versionIndex.value >= 0 ? String(versions.data.value[versionIndex.value]?.content || '') : '')
const lineDiff = computed(() => { const current = new Set((item.value?.content || '').split('\n')); const previous = new Set(versionContent.value.split('\n')); return [...[...previous].filter(line => !current.has(line)).map(line => `− ${line}`), ...[...current].filter(line => !previous.has(line)).map(line => `+ ${line}`)].join('\n') })
function create() { editRecord.value = undefined; formOpen.value = true }
function edit() { editRecord.value = item.value as unknown as Record<string, unknown>; formOpen.value = true }
</script>
<template>
  <PageTitle title="数字图书馆与 Skill" subtitle="组织知识共享经过验证的方法，个人记忆保留员工的连续工作上下文。" eyebrow="KNOWLEDGE / SHARED CAPABILITIES"><el-button type="primary" :icon="Plus" @click="create">新增资料</el-button></PageTitle>
  <div class="work-toolbar"><el-tabs v-model="tab"><el-tab-pane label="全部资料" name="all"/><el-tab-pane label="原始资料" name="SOURCE"/><el-tab-pane label="Wiki" name="WIKI"/><el-tab-pane label="经验沉淀" name="EXPERIENCE"/><el-tab-pane label="Skills" name="SKILL"/><el-tab-pane label="个人记忆" name="MEMORY"/></el-tabs><el-input v-model="query" :prefix-icon="Search" clearable placeholder="检索标题与正文" aria-label="检索知识"/></div>
  <ResourceState v-if="tab === 'MEMORY'" :loading="employees.loading.value" :error="employees.error.value" :empty="!employees.data.value.length" description="暂无可见员工" @retry="employees.load"><div class="card-grid"><RouterLink v-for="employee in employees.data.value" :key="employee.id" :to="`/employees/${employee.id}`" class="panel knowledge-card"><span class="avatar">{{ employee.name.slice(0,1) }}</span><h2>{{ employee.name }} 的记忆</h2><p>在员工工作空间查看核心记忆、工作承诺与来源索引。</p><span class="text-link">进入个人工作空间 →</span></RouterLink></div></ResourceState>
  <ResourceState v-else :loading="knowledge.loading.value" :error="knowledge.error.value" :empty="!items.length" description="暂无符合条件的组织资料" @retry="knowledge.load"><div class="card-grid"><button v-for="entry in items" :key="entry.id" class="panel knowledge-card" @click="selected = entry.id; versionIndex = -1"><div class="spread"><span class="avatar"><Sparkles v-if="entry.kind === 'SKILL'" :size="21"/><BookOpen v-else-if="entry.kind === 'WIKI'" :size="21"/><FileText v-else :size="21"/></span><StatusTag :value="entry.status"/></div><div class="eyebrow">{{ label(entry.kind) }} · V{{ entry.revision }}</div><h2>{{ entry.title }}</h2><p>{{ entry.content.slice(0,150) }}</p><div class="spread"><StatusTag :value="entry.verification"/><span class="caption">{{ entry.source_refs.length }} 项来源</span></div></button></div></ResourceState>
  <section v-if="tab === 'SKILL'" class="panel skill-proposals"><div class="panel-heading"><h2><GitBranch :size="18"/>技能成长提案</h2><span class="caption">按服务端验证与发布状态呈现</span></div><ResourceState :loading="proposals.loading.value" :error="proposals.error.value" :empty="!proposals.data.value.length" description="暂无技能提案" @retry="proposals.load"><el-table :data="proposals.data.value"><el-table-column prop="title" label="技能提案" min-width="180"/><el-table-column prop="revision" label="版本" width="80"/><el-table-column label="状态" width="120"><template #default="{ row }"><StatusTag :value="row.status"/></template></el-table-column><el-table-column label="验证状态" width="120"><template #default="{ row }"><StatusTag :value="row.verification"/></template></el-table-column><el-table-column prop="created_by_actor" label="提出者" min-width="180"/></el-table></ResourceState></section>
  <el-drawer :model-value="!!selected" title="知识与版本详情" size="min(680px, 96vw)" @close="selected = ''"><ResourceState :loading="detail.loading.value" :error="detail.error.value" @retry="detail.load"><template v-if="item"><div class="spread"><StatusTag :value="item.kind"/><el-button :icon="Pencil" @click="edit">更新资料</el-button></div><h1>{{ item.title }}</h1><div class="tag-wrap"><StatusTag :value="item.status"/><StatusTag :value="item.verification"/><el-tag type="info">版本 {{ item.revision }}</el-tag></div><pre class="knowledge-body">{{ item.content }}</pre><h3>来源证据</h3><ul v-if="item.source_refs.length" class="source-list"><li v-for="source in item.source_refs" :key="source">{{ source }}</li></ul><p v-else class="muted">未关联来源证据。</p><div class="divider"></div><h3>版本与验证</h3><ResourceState :loading="versions.loading.value" :error="versions.error.value" :empty="!versions.data.value.length" description="暂无可见版本记录" @retry="versions.load"><div v-for="(version,index) in versions.data.value" :key="String(version.id)" class="mini-card"><div class="spread"><strong>版本 {{ version.version || version.revision }}</strong><StatusTag :value="String(version.status || '')"/></div><pre class="code-block">{{ json(version) }}</pre><el-button text @click="versionIndex = index">与当前正文比较</el-button></div><pre v-if="versionIndex >= 0" class="code-block">{{ lineDiff || '正文内容一致' }}</pre></ResourceState></template></ResourceState></el-drawer>
  <EntityForm v-model="formOpen" kind="knowledge" :record="editRecord"/>
  <section class="panel"><div class="panel-heading"><h2>历史来源与证据归档</h2><span class="caption">按当前可见授权读取，内容需通过 SHA256 核验</span></div><ResourceState :loading="history.loading.value" :error="history.error.value" :empty="!history.data.value.length" description="尚无可见的已迁入历史档案" @retry="history.load"><el-table :data="history.data.value"><el-table-column prop="kind" label="来源类别" min-width="160"/><el-table-column prop="sha256" label="内容哈希" min-width="250"/><el-table-column prop="visibility" label="可见范围" width="100"/><el-table-column label="历史操作" width="140"><template #default="{ row }"><el-button text @click="historyId = row.id">核验并读取</el-button></template></el-table-column></el-table></ResourceState></section>
  <el-drawer :model-value="!!historyId" title="经核验的历史归档内容" size="min(720px, 96vw)" @close="historyId = ''"><ResourceState :loading="historyContent.loading.value" :error="historyContent.error.value" @retry="historyContent.load"><template v-if="historyContent.data.value"><p class="mono">SHA256 {{ historyContent.data.value.sha256 }}</p><pre class="knowledge-body">{{ json(historyContent.data.value.content) }}</pre></template></ResourceState></el-drawer>
</template>
